@router.get("/observability/traces/{trace_id}/spans")
async def get_trace_span_details(
    trace_id: str,
    current_user: User = Depends(get_current_user),
    trace_backend: JaegerClient = Depends(get_trace_client)
):
    spans = await trace_backend.query_spans(trace_id=trace_id)
    if not spans:
        raise HTTPException(status_code=404, detail="Trace spans not found")

    trace_project = spans[0].tags.get("service.project_id")
    if trace_project != current_user.project_id and not current_user.is_platform_admin:
        raise HTTPException(status_code=403, detail="Forbidden: unauthorized to inspect trace telemetry of another project")

    return {
        "trace_id": trace_id,
        "spans": [
            {
                "span_id": s.id,
                "operation": s.operation_name,
                "db_statement": s.tags.get("db.statement"),
                "http_payload": s.tags.get("http.request_body")
            }
            for s in spans
        ]
    }
